#include <stdio.h>
#include <stdlib.h>

static int read_int(void) {
    int c = getchar_unlocked();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = getchar_unlocked();
    int sgn = 1;
    if (c == '-') { sgn = -1; c = getchar_unlocked(); }
    int x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return x * sgn;
}

int main(void) {
    int n = read_int();
    long long *a = (long long *)malloc(sizeof(long long) * (size_t)n);
    for (int i = 0; i < n; i++) a[i] = read_int();

    int i = 0, j = n - 1;
    long long ops = 0;
    while (i < j) {
        if (a[i] == a[j]) {
            i++;
            j--;
        } else if (a[i] < a[j]) {
            a[i + 1] += a[i];
            i++;
            ops++;
        } else {
            a[j - 1] += a[j];
            j--;
            ops++;
        }
    }

    printf("%lld\n", ops);
    free(a);
    return 0;
}
